export function travelText(lang,key,values={}) {
  const value=travelCopy[key]?.[lang]??travelCopy[key]?.en;
  if(typeof value!=='string')throw new Error(`Missing travel copy: ${key}/${lang}`);
  return value.replace(/\{(\w+)\}/g,(token,name)=>name in values?String(values[name]):token);
}

// The interest choices offered on the inquiry form, in display order.
export const inquiryInterests=['nature','culture','river','activity','food','easy'];
export const interestKey=id=>`interest${id[0].toUpperCase()}${id.slice(1)}`;
